"use client";

import { Search } from "lucide-react";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";

import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";

export function SuccessStoriesAdminFilter() {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const querySearch = searchParams.get("search") ?? "";
  const status = searchParams.get("status") ?? "all";
  const featured = searchParams.get("isFeatured") ?? "all";
  const [search, setSearch] = useState(querySearch);

  useEffect(() => {
    setSearch(querySearch);
  }, [querySearch]);

  function updateParams(next: {
    search?: string;
    status?: string;
    featured?: string;
  }) {
    const params = new URLSearchParams(searchParams.toString());
    params.set("page", "1");
    const values = {
      search: next.search ?? search,
      status: next.status ?? status,
      isFeatured: next.featured ?? featured,
    };

    for (const [key, value] of Object.entries(values)) {
      if (value && value !== "all") {
        params.set(key, value);
      } else {
        params.delete(key);
      }
    }

    const query = params.toString();
    router.replace(query ? `${pathname}?${query}` : pathname, {
      scroll: false,
    });
  }

  function clearFilters() {
    setSearch("");
    router.replace(pathname, { scroll: false });
  }

  return (
    <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
      <label className="relative flex-1">
        <Search
          aria-hidden="true"
          size={16}
          className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-muted"
        />
        <Input
          value={search}
          onChange={(event) => {
            const value = event.target.value;
            setSearch(value);
            updateParams({ search: value });
          }}
          placeholder="Search by name or university"
          aria-label="Search by name or university"
          className="pl-9"
        />
      </label>

      <div className="flex flex-col gap-3 sm:flex-row">
        <Select
          value={status}
          onChange={(event) => updateParams({ status: event.target.value })}
          aria-label="Filter by story status"
          className="sm:w-40"
        >
          <option value="all">All statuses</option>
          <option value="pending">Pending</option>
          <option value="approved">Approved</option>
          <option value="rejected">Rejected</option>
        </Select>
        <Select
          value={featured}
          onChange={(event) => updateParams({ featured: event.target.value })}
          aria-label="Filter featured stories"
          className="sm:w-40"
        >
          <option value="all">All stories</option>
          <option value="true">Featured only</option>
          <option value="false">Unfeatured only</option>
        </Select>
        <button
          type="button"
          onClick={clearFilters}
          className="h-10 cursor-pointer px-3 text-sm text-muted hover:text-primary"
        >
          Clear filters
        </button>
      </div>
    </div>
  );
}
